import { chromium } from "playwright";
import { createServer } from "node:http";
import { readFileSync, existsSync } from "node:fs";
import { extname, join } from "node:path";

const WEB = "/Users/sinchunyeung/.treehouse/simplification-of-trajectory-streams-bec452/3/simplification-of-trajectory-streams/web";
const MIME = {
  ".html": "text/html; charset=utf-8",
  ".js": "text/javascript; charset=utf-8",
  ".png": "image/png",
  ".css": "text/css; charset=utf-8",
  ".json": "application/json",
};

function makeStep(streamIdx, pi, p0) {
  return {
    stream_idx: streamIdx,
    pi,
    Gi: [
      [pi[0] - 0.4, pi[1] - 0.4],
      [pi[0] + 0.4, pi[1] - 0.4],
      [pi[0] + 0.4, pi[1] + 0.4],
      [pi[0] - 0.4, pi[1] + 0.4],
    ],
    buffer: [p0, pi],
    candidates: [{ grid_pt_idx: 0, alive: true, S: [pi], F: [], F_Si: [] }],
  };
}

function makePrefix(p0, p0Idx, points) {
  return {
    p0,
    p0_idx: p0Idx,
    P: [p0],
    end_idx: p0Idx + points.length,
    output: [p0, points[points.length - 1]],
    steps: points.map((pi, i) => makeStep(p0Idx + i + 1, pi, p0)),
  };
}

const stream = [
  [0, 0],
  [1, 0.2],
  [2, 0.1],
  [3, 0.8],
  [4, 1.1],
];
const ndjson = [
  JSON.stringify({
    type: "header",
    eps: 0.9,
    delta: 500,
    grid_val: 1,
    r_val: 1.2,
    expected_frechet: 1.4,
    bbox: [-0.5, -0.5, 4.5, 1.6],
    stream,
  }),
  JSON.stringify({
    type: "prefix",
    data: makePrefix([0, 0], 0, [
      [1, 0.2],
      [2, 0.1],
    ]),
  }),
  JSON.stringify({
    type: "prefix",
    data: makePrefix([2, 0.1], 2, [
      [3, 0.8],
      [4, 1.1],
    ]),
  }),
  JSON.stringify({
    type: "done",
    time_ms: 44,
    simplified: [
      [0, 0],
      [2, 0.1],
      [4, 1.1],
    ],
    frechet_distance: null,
  }),
].join("\n") + "\n";

const server = createServer((req, res) => {
  const url = new URL(req.url, "http://127.0.0.1");
  let filePath = join(WEB, url.pathname === "/" ? "index.html" : url.pathname);
  if (!existsSync(filePath)) {
    res.writeHead(404);
    res.end("not found");
    return;
  }
  const body = readFileSync(filePath);
  res.writeHead(200, { "Content-Type": MIME[extname(filePath)] || "application/octet-stream" });
  res.end(body);
});

await new Promise((resolve) => server.listen(8765, "127.0.0.1", resolve));

const browser = await chromium.launch({ headless: true });

async function withRoutes(page) {
  await page.route("**/api/traces", (route) =>
    route.fulfill({
      json: { traces: [{ id: 1, n_points: 5, label: "Demo", epsilon: 0.9, delta: 500 }] },
    }),
  );
  await page.route("**/api/frechet", (route) => route.fulfill({ json: { distance: 1.25 } }));
  await page.route("**/api/trace/**", (route) =>
    route.fulfill({
      status: 200,
      contentType: "application/x-ndjson",
      body: ndjson,
    }),
  );
}

async function loadTrace(page, mobile) {
  await page.goto("http://127.0.0.1:8765/", { waitUntil: "domcontentloaded" });
  if (mobile) {
    await page.locator("#preloadedTrigger").click();
    await page.locator(".trace-picker-item").first().click();
  } else {
    await page.locator("#traceSelect").selectOption("1");
  }
  await page.locator("#loadBtn").click();
  await page.waitForFunction(() => document.body.classList.contains("playback-ready"), {
    timeout: 10000,
  });
}

try {
  const fixture = await browser.newPage({ viewport: { width: 1280, height: 900 } });
  await fixture.goto("http://127.0.0.1:8765/usability/playback-end-stop.html", {
    waitUntil: "domcontentloaded",
  });
  await fixture.screenshot({
    path: join(WEB, "usability/playback-end-stop.png"),
    fullPage: true,
  });
  await fixture.close();

  const desktop = await browser.newPage({ viewport: { width: 1280, height: 800 } });
  await withRoutes(desktop);
  await loadTrace(desktop, false);
  await desktop.locator('#playbackBar .speed-preset[data-speed="4"]').click();
  await desktop.locator("#playBtn").click();
  await desktop.waitForFunction(() => {
    const label = document.querySelector("#playBtn .play-label");
    return label && label.textContent === "Play";
  }, { timeout: 8000 });
  const desktopPlaying = await desktop.evaluate(
    () => document.querySelector("#playBtn .play-label")?.textContent,
  );
  const desktopStep = await desktop.locator("#stepInput").inputValue();
  const desktopSeg = await desktop.locator("#segmentInput").inputValue();
  console.log("desktop after play", { desktopPlaying, desktopStep, desktopSeg });
  if (desktopPlaying !== "Play") throw new Error("desktop Play did not restore");
  if (!desktopStep.startsWith("2") || !desktopSeg.startsWith("2")) {
    throw new Error(`desktop not on last frame: step=${desktopStep} seg=${desktopSeg}`);
  }
  await desktop.screenshot({
    path: join(WEB, "usability/desktop-playback-end-live.png"),
  });
  await desktop.close();

  const mobile = await browser.newPage({
    viewport: { width: 390, height: 844 },
    isMobile: true,
    hasTouch: true,
  });
  await withRoutes(mobile);
  await loadTrace(mobile, true);
  await mobile.locator('#mobileTransport .speed-preset[data-speed="4"]').click();
  await mobile.locator("#mobilePlayBtn").click();
  await mobile.waitForFunction(() => {
    const label = document.querySelector("#mobilePlayBtn .mobile-play-label");
    return label && label.textContent === "Play";
  }, { timeout: 8000 });
  const mobilePlaying = await mobile.evaluate(
    () => document.querySelector("#mobilePlayBtn .mobile-play-label")?.textContent,
  );
  const mobileStep = await mobile.evaluate(() => document.querySelector("#stepInput")?.value);
  const mobileSeg = await mobile.evaluate(() => document.querySelector("#segmentInput")?.value);
  console.log("mobile after play", { mobilePlaying, mobileStep, mobileSeg });
  if (mobilePlaying !== "Play") throw new Error("mobile Play did not restore");
  if (!String(mobileStep).startsWith("2") || !String(mobileSeg).startsWith("2")) {
    throw new Error(`mobile not on last frame: step=${mobileStep} seg=${mobileSeg}`);
  }
  await mobile.screenshot({
    path: join(WEB, "usability/mobile-playback-end-live.png"),
  });
  await mobile.close();

  console.log("ok");
} finally {
  await browser.close();
  server.close();
}
